def transform(grid):
    n=len(grid); m=len(grid[0])
    by_diag={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:
                d=c-r
                if d in by_diag and by_diag[d]!=v:
                    raise ValueError('inconsistent diagonal')
                by_diag[d]=v
    colors=set(by_diag.values())
    if len(colors)==1:
        v=next(iter(colors))
        return [[v]*m for _ in range(n)]
    period=len(by_diag)
    residue_map={}
    for d,v in by_diag.items():
        k=d%period
        if k in residue_map and residue_map[k]!=v:
            raise ValueError('residue conflict')
        residue_map[k]=v
    if len(residue_map)!=period:
        raise ValueError('incomplete')
    return [[residue_map[(c-r)%period] for c in range(m)] for r in range(n)]

demo1=[[7,7,7],[7,7,7],[0,0,0]]
print(transform(demo1))
